What will the stream output?
```javascript
const fs = require('fs');
const stream = fs.createReadStream('bigfile.txt', { highWaterMark: 16384 });
stream.on('data', (chunk) => {
  console.log(`received chunk: ${chunk.length} bytes`);
});
stream.on('end', () => console.log('done'));
```

